import {similarityReview} from '../reports/similarity-review.mjs';
import {similarityScopeNotice,similarityLimitedNotice} from './report-copy.mjs';
import {similarityLocations,locationExcerpt} from '../reports/report-locations.mjs';
import {reportStatistics} from './report-statistics.mjs';
import {highlightHtml} from './report-highlight.mjs';
import {sliceCp} from './engine.mjs';
import {publicSourceHref as sourceHref} from './source-url.mjs';
import {reportDocument,reportEscape as esc} from '../reports/report-document.mjs';
// A presentation/export view only: stored evidence, source text, match offsets
// and original report objects stay unchanged.
export function sourceExportView(source){
 if(!source||typeof source!=='object')return source;
 const url=sourceHref(source.url);
 return {...source,url,...(source.url&&!url?{urlRedacted:true}:{})};
}
export function reportExportView(report){
 return {...report,...(Array.isArray(report.sources)?{sources:report.sources.map(sourceExportView)}:{}),...(report.web&&typeof report.web==='object'?{web:{...report.web,...(Array.isArray(report.web.sources)?{sources:report.web.sources.map(sourceExportView)}:{})}}:{})};
}
export function sourceCopyText(source){
 const safe=sourceExportView(source);
 return `${safe.title}\n作者：${safe.authors?.join('、')||'未提供'}\n年份：${safe.year||'未提供'}\n来源：${safe.provider||'未提供'}\nDOI：${safe.doi||'未提供'}\nURL：${safe.url||(safe.urlRedacted?'链接已隐藏':'未提供')}`;
}
const fmt=n=>Number(n||0).toLocaleString('zh-CN');
const pct=n=>Number.isFinite(n)?(n*100).toFixed(1):'—';
const metric=(label,value,note='')=>`<div class="report-metric"><small>${esc(label)}</small><strong>${esc(value)}</strong>${note?`<em>${esc(note)}</em>`:''}</div>`;
export function webCoverageHtml(report){
 const limited=report.web?.searchComplete===false||Number(report.web?.failedSources)>0;
 return `<section class="report-panel"><h2 class="report-section-title">检测范围说明</h2><p>${esc(similarityScopeNotice)}</p>${limited?`<p>${esc(similarityLimitedNotice)}</p>`:''}</section>`;
}
export function reportHtml(report){
 const sources=report.sources||[],sections=report.sections||[],included=sections.filter(s=>s.included),sourceMap=new Map(sources.map((s,i)=>[s.id,{...s,number:i+1}])),isDemo=report.mode==='demo'||sources.some(s=>s.kind==='demo'),isWeb=report.mode==='web';
 const stats=reportStatistics(report),locations=similarityLocations(report),findings=locations.filter(row=>row.matches.length);
 const findingIndex=`<section class="report-panel" id="report-findings"><h2 class="report-section-title">二  原文问题定位</h2>${findings.length?`<p>共有 ${findings.length} 段原文存在实际文字匹配。点击定位原文或查看左右对照，核对具体文字与来源。</p><table class="report-table report-findings-table"><thead><tr><th style="width:23%">原文位置</th><th>论文原文摘录</th><th style="width:23%">匹配来源与对照</th></tr></thead><tbody>${findings.map(row=>{const first=row.matches[0],excerpt=locationExcerpt(row.paragraph.text,first.range[0],first.range[1]),from=excerpt.start,to=excerpt.end,shown=sliceCp(row.paragraph.text,from,to),matches=row.matches.map(m=>({...m,range:[Math.max(0,m.range[0]-from),Math.min(to-from,m.range[1]-from)],excludedRanges:(m.excludedRanges||[]).map(([a,b])=>[a-from,b-from])})).filter(m=>m.range[1]>m.range[0]);return `<tr><td>${esc(row.section.title)}<br><small>第 ${row.index} 段</small><br><a href="#${row.target}">定位原文 ↓</a></td><td><p class="report-text">${from?'…':''}${highlightHtml(shown,matches)}${to<Array.from(row.paragraph.text).length?'…':''}</p></td><td>${[...new Set(row.matches.map(m=>m.sourceId))].map(id=>sourceMap.get(id)).filter(Boolean).map(source=>`<a href="#source-${source.number}">[${source.number}] ${esc(source.title)}</a>`).join('<br>')}<br><a class="report-locate-link" href="#${row.comparisonTarget}">查看左右对照 ↓</a></td></tr>`;}).join('')}</tbody></table>`:'<p>本次检测未发现匹配段落。全文保留在下方供核对。</p>'}</section>`;
 const scope=isWeb?'本次纳入的比对资料':isDemo?'演示材料与指定对照正文':'用户提供的本地对照正文';
 const sourceRows=sources.map((s,i)=>`<tr><td style="width:7%">${i+1}</td><td><a href="#source-${i+1}"><b>${esc(s.title)}</b></a><div class="report-source-info">${esc(s.authors?.join('、')||'作者未提供')} · ${esc(s.year||'年份未提供')}</div></td><td style="width:22%">${fmt(stats.sourceCharacters.get(s.id))}<div class="report-source-info">${pct((stats.sourceCharacters.get(s.id)||0)/Math.max(1,report.totalChars))}%</div><div class="report-bar"><span style="width:${Math.min(100,Math.max(0,(stats.sourceCharacters.get(s.id)||0)/Math.max(1,report.totalChars)*100))}%"></span></div></td></tr>`).join('');
 const summary=`<section class="report-panel" id="report-summary"><h2 class="report-section-title">一  检测结果总览</h2><div class="report-metrics">${metric(isWeb?'文字重复率':'文字相似占比',pct(report.ratio)+'%','查看原文标注与来源对照')}${metric('单篇最大文字相似比',pct(stats.maximumRatio)+'%',stats.maximum.source?.title||'本次无匹配来源')}${metric('参与检测字符',fmt(report.totalChars),'本次参与检测的正文')}${metric('匹配字符',fmt(report.similarChars),`${report.sourceCount||0} 个命中来源 / ${sources.length} 份对照材料`)}</div><p class="report-muted">${isWeb?esc(similarityScopeNotice):'结果仅针对本次提供的对照材料，不保证覆盖其他文献。'}</p></section><section class="report-panel"><h2 class="report-section-title">文字指标与检测项目</h2><table class="report-table report-statistics"><tbody><tr><th>检测段落数</th><td>${fmt(stats.paragraphs)}</td><th>匹配段落数</th><td>${fmt(stats.matchedParagraphs)}</td></tr><tr><th>最长连续匹配字符</th><td>${fmt(stats.longestMatch)}</td><th>单篇最大匹配字符</th><td>${fmt(stats.maximum.characters)}</td></tr><tr><th>去除引用后相似占比</th><td>${isWeb?'未计算':pct(report.uncitedRatio)+'%'}</td><th>去除本人文献后相似占比</th><td>未计算</td></tr></tbody></table><p class="report-muted">未计算的项目不显示为0%；引用识别及本人已发表文献排除范围须有相应依据，不能由总相似占比推算。</p></section>${findingIndex}<section class="report-panel" id="report-chapters"><h2 class="report-section-title">三  章节检测结果</h2><table class="report-table"><thead><tr><th style="width:42%">章节名称</th><th>检测字符</th><th>匹配字符</th><th>相似占比</th></tr></thead><tbody>${sections.map(s=>`<tr><td>${esc(s.title)}${s.included?'':' <span class="report-badge">未参与检测</span>'}</td><td>${s.included?fmt(s.totalChars):'—'}</td><td>${s.included?fmt(s.similarChars):'—'}</td><td>${s.included?pct(s.ratio)+'%':'—'}</td></tr>`).join('')}</tbody></table></section><section class="report-panel" id="report-sources"><h2 class="report-section-title">四  相似来源概览</h2>${sources.length?`<table class="report-table"><thead><tr><th style="width:7%">编号</th><th>对照材料</th><th style="width:22%">匹配字符及占比</th></tr></thead><tbody>${sourceRows}</tbody></table>`:'<div class="report-empty">没有记录可展示的来源材料。</div>'}<p class="report-muted">同一正文片段可能对应多个来源，各来源命中字符不可直接相加。</p></section>`;
 const body=`${similarityReview(report,sourceMap)}<section class="report-panel report-page-break" id="report-evidence"><h2 class="report-section-title">六  对照材料与来源信息</h2>${sources.map((s,i)=>{const href=sourceHref(s.url);return `<article class="report-evidence" id="source-${i+1}"><div class="report-evidence-head"><h3 class="report-source-title">[${i+1}] ${esc(s.title)}</h3><div class="report-source-info">${esc(s.authors?.join('、')||'作者未提供')} · ${esc(s.year||'年份未提供')} · ${esc(isWeb?'比对资料':s.provider||'来源未提供')}</div></div><div class="report-evidence-body"><p class="report-source-info">DOI：${esc(s.doi||'未提供')}<br>URL：${href?`<a href="${esc(href)}" rel="noreferrer noopener">${esc(href)}</a>`:(s.url?'链接已隐藏':'未提供')}<br>材料类型：${isWeb?'比对资料':s.kind==='demo'?'演示材料':'用户提供'}</p>${isWeb?'<p class="report-muted">仅展示与本次文稿有关的对照片段，不附录来源网页全文。命中证据见上方正文标注与片段对照。</p>':`<p class="report-text">${esc(s.text)}</p>`}</div></article>`;}).join('')}</section><section class="report-panel" id="report-method"><h2 class="report-section-title">七  检测说明</h2><ol class="report-notes"><li>本次检测包含 ${included.length} 个章节。请结合全文标注、章节结果与来源对照核对重复内容。</li><li>有匹配不等于不当使用，请核对引用是否规范。未提供的检测项目显示为“未计算”。</li><li>本报告为重复率检测报告，AI 率需单独检测。</li><li>报告编号用于定位本次检测记录。正文修改后需重新检测，原报告数值保持不变。</li></ol>${isWeb?`${webCoverageHtml(report)}`:''}</section>`;
 return reportDocument({title:report.title,type:isWeb?'论文重复率检测报告':'文本相似性检测报告',id:report.id,createdAt:report.createdAt,scope,navigation:[['report-summary','检测总览'],['report-findings','原文问题定位'],['report-chapters','章节结果'],['report-sources','相似来源'],['report-text','全文标注'],['report-evidence','来源对照'],['report-method','检测说明']],metadata:[['作者',report.author||'未提供'],['学段 / 身份',report.degree||'未提供'],['原文件',report.fileName||'粘贴正文'],['报告状态',report.complete===false?'未完整完成':'比对已完成']],notice:isWeb?similarityScopeNotice:'材料比对报告。结果仅来自本次指定的对照材料，供来源核对和修改参考，不替代学校或机构指定的检测报告。',summary,body,demo:isDemo});
}
